{
  "definition_simple": "a fact, event, or situation that can be seen or observed, especially something unusual or hard to explain",
  "definition_standard": "an observable fact, occurrence, or circumstance, especially one whose cause or explanation is in question or of scientific interest",
  "pos": "noun",
  "semantic_class": "abstract",
  "sentences": [
    {
      "text": "Rainbows are a common natural phenomenon that many children love to see.",
      "tier": "T1"
    },
    {
      "text": "The northern lights are a stunning phenomenon that attracts tourists every winter.",
      "tier": "T2"
    },
    {
      "text": "Scientists study this rare weather phenomenon to better understand thunderstorm patterns.",
      "tier": "T2"
    },
    {
      "text": "Online shopping has become a worldwide phenomenon over the past two decades.",
      "tier": "T3"
    },
    {
      "text": "Sleep paralysis is a frightening biological phenomenon that affects millions of people.",
      "tier": "T3"
    },
    {
      "text": "Sociologists investigated the cultural phenomenon behind viral dance crazes among adolescents.",
      "tier": "T4"
    },
    {
      "text": "The rapid expansion of social media influencers represents an unprecedented commercial phenomenon.",
      "tier": "T4"
    },
    {
      "text": "Physicists sought to replicate the anomalous quantum phenomenon under strictly controlled laboratory conditions.",
      "tier": "T5"
    },
    {
      "text": "The sudden collapse of the regional ecosystem was an unprecedented ecological phenomenon.",
      "tier": "T5"
    },
    {
      "text": "Epistemological inquiry often struggles to reconcile subjective sensory experience with the objective nature of a phenomenon.",
      "tier": "T6"
    }
  ],
  "morphological_forms": [
    {
      "form": "phenomena",
      "label": "plural"
    },
    {
      "form": "phenomenon's",
      "label": "singular_possessive"
    }
  ],
  "morphology_wrong_forms": [
    {
      "base_form": "phenomena",
      "wrong_form": "phenomenons",
      "explanation": "Learners overregularize by adding the standard English plural suffix '-s' instead of retaining the classical Greek neuter plural ending '-a'."
    },
    {
      "base_form": "phenomena",
      "wrong_form": "phenomenas",
      "explanation": "Learners mistakenly treat the irregular plural 'phenomena' as a singular noun and attach an additional plural suffix '-s'."
    },
    {
      "base_form": "phenomena",
      "wrong_form": "phenomenies",
      "explanation": "Learners mistakenly apply the '-ies' pluralization pattern as if the word ended in a consonant plus 'y'."
    },
    {
      "base_form": "phenomenon's",
      "wrong_form": "phenomenas'",
      "explanation": "Learners conflate the irregular plural with a regular singular noun and add an apostrophe after an incorrectly formed plural."
    },
    {
      "base_form": "phenomenon's",
      "wrong_form": "phenomenon",
      "explanation": "Learners omit the possessive marker entirely when attempting to indicate ownership or attribution."
    },
    {
      "base_form": "phenomenon's",
      "wrong_form": "phenomenones",
      "explanation": "Learners falsely generalize Romance-style plural or genitive inflections by adding '-es' directly without an apostrophe."
    }
  ],
  "l1_audio_confusables": [
    {
      "word": "pheromone",
      "explanation": "Shares initial bilabial and nasal consonants and similar syllable onset rhythm (/fəˈnɒm.../ vs. /ˈfɛr.ə.moʊn/), leading to acoustic confusion in fast speech."
    },
    {
      "word": "phenotype",
      "explanation": "Shares the initial 'pheno-' acoustic prefix (/fiːn-/ or /fɛn-/), causing listeners to mistake one scientific abstract noun for the other."
    },
    {
      "word": "frenetic",
      "explanation": "Shares the unstressed /fr/ or /f/ onset followed by nasal and alveolar transitions, causing auditory misperception in noisy environments."
    }
  ],
  "primary_collocate": "natural",
  "collocation_distractors": [
    {
      "word": "organic",
      "explanation": "'Organic' describes biological farming or chemical composition and does not form an idiomatic fixed descriptor with 'phenomenon' like 'natural' does."
    },
    {
      "word": "wild",
      "explanation": "'Wild' modifies untamed animals or uncontrolled behavior rather than observable occurrences or scientific events."
    },
    {
      "word": "elemental",
      "explanation": "While semantically adjacent to forces of nature, 'elemental' typically collocates with 'forces' or 'fury' rather than 'phenomenon'."
    }
  ],
  "collocation_wrong_collocate": "unartificial",
  "cloze_distractors": [
    {
      "word": "illusion",
      "explanation": "Wrong sense: an illusion denotes a false perception or deceptive appearance, whereas a phenomenon denotes an actual observable reality."
    },
    {
      "word": "incident",
      "explanation": "Wrong register and framing: an incident denotes an isolated, often discrete human or operational mishap rather than a broad, observable scientific occurrence."
    },
    {
      "word": "utensil",
      "explanation": "Trivially unrelated: a utensil is a physical handheld tool for household tasks and makes no semantic sense in an observational scientific context."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "text": "The volcanic eruption phenomenoned across the entire island chain within hours.",
      "linguistic_reason": "Syntactic category error: 'phenomenon' is exclusively a noun and cannot be inflected or used as a finite verb."
    },
    {
      "text": "These rare phenomenon have baffled astronomers for nearly half a century.",
      "linguistic_reason": "Number agreement error: 'phenomenon' is singular and cannot agree with the plural demonstrative 'these' or the plural verb 'have baffled'; the plural 'phenomena' is required."
    },
    {
      "text": "The meteorologist gave a phenomenon of the unusual storm system to the press.",
      "linguistic_reason": "Collocational and argument structure error: 'phenomenon' is an observable occurrence itself, not an act of communication or presentation; the noun 'explanation' or 'account' is required."
    }
  ],
  "spot_incorrect": {
    "sentence": "Scientists are carefully documenting this unprecedented biological phenomena to determine its origin.",
    "error_description": "The plural form 'phenomena' is incorrectly used with the singular demonstrative determiner 'this'.",
    "corrected_sentence": "Scientists are carefully documenting this unprecedented biological phenomenon to determine its origin."
  },
